from dataclasses import dataclass
import warnings


def _rows(value: object) -> None:
    if not isinstance(value, tuple):
        raise TypeError("rows must be a tuple")
    if any(not isinstance(row, tuple) for row in value):
        raise TypeError("each row must be a tuple")


def _non_negative_number(value: object, name: str) -> None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{name} must be numeric")
    if value < 0:
        raise ValueError(f"{name} must be non-negative")


@dataclass(frozen=True)
class Observation:
    rows: tuple[tuple[object, ...], ...]
    elapsed_ms: float

    def __post_init__(self) -> None:
        _rows(self.rows)
        _non_negative_number(self.elapsed_ms, "elapsed_ms")


@dataclass(frozen=True)
class Expectation:
    rows: tuple[tuple[object, ...], ...]
    contained_count: int
    maximum_ms: float | None

    def __post_init__(self) -> None:
        _rows(self.rows)
        if isinstance(self.contained_count, bool) or not isinstance(self.contained_count, int):
            raise TypeError("contained_count must be an integer")
        if self.contained_count < 0:
            raise ValueError("contained_count must be non-negative")
        if self.maximum_ms is not None:
            _non_negative_number(self.maximum_ms, "maximum_ms")


class ResultAuditor:
    @staticmethod
    def _validate(observation: Observation, expectation: Expectation) -> None:
        if not isinstance(observation, Observation):
            raise TypeError("observation must be an Observation")
        if not isinstance(expectation, Expectation):
            raise TypeError("expectation must be an Expectation")

    @staticmethod
    def assert_exact(observation: Observation, expectation: Expectation) -> None:
        ResultAuditor._validate(observation, expectation)
        if observation.rows != expectation.rows:
            raise AssertionError("rows do not match exactly")

    @staticmethod
    def assert_contained(observation: Observation, expectation: Expectation) -> None:
        ResultAuditor._validate(observation, expectation)
        remaining = list(expectation.rows)
        matches = 0
        for row in observation.rows:
            for index, candidate in enumerate(remaining):
                if row == candidate:
                    matches += 1
                    break
        if matches != expectation.contained_count:
            raise AssertionError(f"expected {expectation.contained_count} contained rows, got {matches}")

    @staticmethod
    def check_runtime(observation: Observation, expectation: Expectation) -> None:
        ResultAuditor._validate(observation, expectation)
        if expectation.maximum_ms is not None and observation.elapsed_ms > expectation.maximum_ms:
            warnings.warn("runtime exceeded the configured maximum", RuntimeWarning, stacklevel=2)

